package com.pvp.travelmatch.controller;
import com.pvp.travelmatch.dto.*; import com.pvp.travelmatch.service.MonetizationService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/monetization") @RequiredArgsConstructor public class MonetizationController{
 private final MonetizationService s; @GetMapping("/status") public PremiumStatusResponse status(){return s.status();} @PostMapping("/premium/order") public PaymentOrderResponse premiumOrder(){return s.createPremiumOrder();} @PostMapping("/premium/verify") public SubscriptionResponse premiumVerify(@Valid @RequestBody PaymentVerificationRequest r){return s.verifyPremium(r);} @PostMapping("/premium/cancel") public SubscriptionResponse cancel(){return s.cancel();} @GetMapping("/profile/views") public java.util.List<ProfileViewResponse> views(){return s.profileViews();} @PostMapping("/boost/{planId}/order") public PaymentOrderResponse boostOrder(@PathVariable Long planId){return s.createBoostOrder(planId);} @PostMapping("/boost/{planId}/verify") public BoostResponse boostVerify(@PathVariable Long planId,@Valid @RequestBody PaymentVerificationRequest r){return s.verifyBoost(planId,r);} @PostMapping(value="/webhook/razorpay",consumes=MediaType.APPLICATION_JSON_VALUE) public ResponseEntity<Void> webhook(@RequestHeader(value="X-Razorpay-Signature",required=false)String sig,@RequestBody String body){s.webhook(body,sig);return ResponseEntity.ok().build();}
}
